<?php if($flash): ?><div class="alert alert-<?= $flash['type'] ?>"><?= htmlspecialchars($flash['message']) ?></div><?php endif ?><div class="card mx-auto" style="max-width:720px"><div class="card-body p-4"><div class="d-flex justify-content-between"><div><div class="page-kicker">Velora Parlour</div><h1 class="h4 mb-1">Tax invoice</h1><div class="text-muted"><?= htmlspecialchars($invoice['invoice_number']) ?> · <?= htmlspecialchars($invoice['created_at']) ?></div></div><button class="btn btn-outline-secondary d-print-none" onclick="print()">Print receipt</button></div><hr><div><strong><?= htmlspecialchars($invoice['customer_name']) ?></strong><br><?= htmlspecialchars($invoice['mobile']??'') ?></div><table class="table mt-3"><thead><tr><th>Item</th><th>Qty</th><th class="text-end">Total</th></tr></thead><tbody><?php foreach($items as $x): ?><tr><td><?= htmlspecialchars($x['description']) ?></td><td><?= $x['quantity'] ?></td><td class="text-end">₹<?= number_format((float)$x['line_total'],2) ?></td></tr><?php endforeach ?></tbody></table><div class="text-end"><div>Subtotal: ₹<?= number_format((float)$invoice['subtotal'],2) ?></div><?php if((float)$invoice['discount_total']>0): ?><div>Discount: -₹<?= number_format((float)$invoice['discount_total'],2) ?></div><?php endif ?><div>Tax: ₹<?= number_format((float)$invoice['tax_total'],2) ?></div><div class="fs-4 fw-bold">Total: ₹<?= number_format((float)$invoice['grand_total'],2) ?></div><div>Paid: ₹<?= number_format((float)$invoice['paid_total'],2) ?> · Balance: ₹<?= number_format((float)$invoice['balance_total'],2) ?></div><p class="text-muted small mt-4 mb-0">Thank you for choosing Velora. We look forward to seeing you again.</p></div></div></div>
